const html = $json.data || "";

const text = html
  .replace(/<script[\s\S]*?<\/script>/gi, " ")
  .replace(/<style[\s\S]*?<\/style>/gi, " ")
  .replace(/<svg[\s\S]*?<\/svg>/gi, " ")
  .replace(/<[^>]+>/g, " ")
  .replace(/&nbsp;/g, " ")
  .replace(/&amp;/g, "&")
  .replace(/&quot;/g, '"')
  .replace(/&#39;/g, "'")
  .replace(/\s+/g, " ")
  .trim();

const blockedOrEmpty =
  text.length < 300 ||
  /doesn't work properly without javascript/i.test(text) ||
  /enable javascript/i.test(text);

return {
  ...$json,
  page_text: text.slice(0, 30000),
  source_quality: blockedOrEmpty ? "poor" : "good",
  needs_fallback: blockedOrEmpty
};

const xml = $json.data || "";

const items = [...xml.matchAll(/<item>([\s\S]*?)<\/item>/g)];

const news = items.slice(0, 10).map((match) => {
  const item = match[1];

  const getTag = (tag) => {
    const result = item.match(
      new RegExp(`<${tag}[^>]*>([\\s\\S]*?)<\\/${tag}>`)
    );
    return result ? result[1].trim() : "";
  };

  return {
    title: getTag("title"),
    link: getTag("link"),
    pubDate: getTag("pubDate"),
    source: getTag("source"),
  };
});

const event = $("If").item.json;

return {
  ...event,
  news_results: news,
  news_count: news.length
};

const text = [
  $json.official_page_text || "",
  $json.news_context || "",
  JSON.stringify($json.json_ld || [])
].join("\n");

const lower = text.toLowerCase();

const topics = [];

const topicMap = [
  ["stablecoin", "Stablecoins"],
  ["tokenization", "Tokenização"],
  ["tokenización", "Tokenização"],
  ["defi", "DeFi"],
  ["cbdc", "CBDC"],
  ["regulation", "Regulação"],
  ["regulación", "Regulação"],
  ["regulação", "Regulação"],
  ["payments", "Pagamentos"],
  ["pagos", "Pagamentos"],
  ["pagamentos", "Pagamentos"],
  ["web3", "Web3"],
  ["blockchain", "Blockchain"],
  ["fintech", "Fintech"],
  ["artificial intelligence", "IA"],
  ["inteligencia artificial", "IA"],
  ["inteligência artificial", "IA"],
  ["venture capital", "Venture Capital"],
  ["investment", "Investimentos"],
  ["inversión", "Investimentos"],
  ["investimento", "Investimentos"],
  ["startup", "Startups"],
  ["innovation", "Inovação"],
  ["innovación", "Inovação"],
  ["inovação", "Inovação"],
  ["trading", "Trading"],
  ["bitcoin", "Bitcoin"]
];

for (const [keyword, label] of topicMap) {
  if (lower.includes(keyword) && !topics.includes(label)) {
    topics.push(label);
  }
}

const organizers = [];

// Primeiro tenta pegar organizadores do JSON-LD
for (const block of $json.json_ld || []) {
  if (block?.["@type"] === "Event" && Array.isArray(block.organizer)) {
    for (const org of block.organizer) {
      if (org?.name && !organizers.includes(org.name)) {
        organizers.push(org.name);
      }
    }
  }
}

// Se não encontrou no JSON-LD, tenta achar no texto oficial
if (organizers.length === 0 && $json.official_page_text) {
  const organizerPatterns = [
    /Organizers?:\s*([^\.]+)/i,
    /Organiza(?:dores?)?:\s*([^\.]+)/i
  ];

  for (const pattern of organizerPatterns) {
    const match = $json.official_page_text.match(pattern);

    if (match?.[1]) {
      organizers.push(match[1].trim());
      break;
    }
  }
}

return {
  ...$json,

  extracted_intelligence: {
    organizer_name: organizers.join(", "),
    main_topics: topics,

    research_status: "researched",
    research_confidence: $json.research_confidence,

    research_notes:
      $json.research_method === "official_page"
        ? "Research based on official event page and structured data."
        : "Research based on recent news fallback."
  }
};

const news = $json.news_results || [];
const html = $json.data || "";

const researchSources = [];

// Extrai JSON-LD antes de ignorar scripts
const jsonLdBlocks = [];

const jsonLdMatches = [
  ...html.matchAll(
    /<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi
  )
];

for (const match of jsonLdMatches) {
  try {
    const parsed = JSON.parse(match[1].trim());
    jsonLdBlocks.push(parsed);
  } catch (e) {
    // ignora blocos inválidos
  }
}

if ($json.source_quality === "good" && $json.source_url) {
  researchSources.push({
    type: "official",
    url: $json.source_url
  });
}

for (const item of news) {
  researchSources.push({
    type: "news",
    title: item.title,
    source: item.source,
    url: item.link,
    published_at: item.pubDate
  });
}

const newsText = news
  .map((item) => `${item.source}: ${item.title}`)
  .join("\n");

return {
  event_id: $json.id,
  title: $json.title,
  city: $json.city,
  country: $json.country,
  start_date: $json.start_date,
  end_date: $json.end_date,
  category: $json.category,
  audience: $json.audience,
  tags: $json.tags,
  source_url: $json.source_url,

  official_page_text:
    $json.source_quality === "good"
      ? ($json.page_text || "")
      : "",

  json_ld: jsonLdBlocks,

  news_context: newsText,

  research_sources: researchSources,

  research_method:
    $json.source_quality === "good"
      ? "official_page"
      : "news_fallback",

  research_confidence:
    $json.source_quality === "good"
      ? "high"
      : news.length >= 3
        ? "medium"
        : "low"
};

