  "why_it_matters",
  "who_should_go",
  "who_should_skip",
  "business_opportunity",
  "networking_opportunity",
  "editorial_angle",
  "agenda_take",
  "regional_context"
];

const errors = [];

// -----------------------------------------------------
// 1. CAMPOS OBRIGATÓRIOS
// -----------------------------------------------------

for (const field of requiredFields) {
  if (
    !parsed[field] ||
    typeof parsed[field] !== "string" ||
    parsed[field].trim().length < 10
  ) {
    errors.push(`Campo inválido ou vazio: ${field}`);
  }
}


// -----------------------------------------------------
// 2. FRASES GENÉRICAS / PROMOCIONAIS
// -----------------------------------------------------

const genericPatterns = [
  /excelente oportunidade/i,
  /evento imperdível/i,
  /conteúdo de qualidade/i,
  /não perca/i,
  /vale muito a pena/i,
  /evento único/i,
  /oportunidade incrível/i,
  /uma experiência única/i
];


// -----------------------------------------------------
// 3. SINAIS DE EXTRAPOLAÇÃO
// -----------------------------------------------------

const unsupportedPatterns = [
  /\bdeve apresentar\b/i,
  /\bdeve contar com\b/i,
  /\bdeve incluir\b/i,
  /\bdeve focar\b/i,
  /\bprovavelmente contará\b/i,
  /\bcertamente\b/i,
  /\bsem dúvida\b/i,
  /\bserá uma referência\b/i,
  /\bé um dos maiores\b/i,
  /\bé um dos principais\b/i,
  /\bé um dos mais importantes\b/i
];


// -----------------------------------------------------
// 4. REPETIÇÃO RUIM
// -----------------------------------------------------

const repetitionPatterns = [
  /networking e networking/i,
  /bitcoin e bitcoin/i,
  /blockchain e blockchain/i
];


// -----------------------------------------------------
// 5. VALIDA CADA CAMPO
// -----------------------------------------------------

for (const field of requiredFields) {
  const value = parsed[field] || "";

  for (const pattern of genericPatterns) {
    if (pattern.test(value)) {
      errors.push(`${field}: linguagem genérica/promocional.`);
      break;
    }
  }

  for (const pattern of unsupportedPatterns) {
    if (pattern.test(value)) {
      errors.push(`${field}: possível extrapolação não comprovada.`);
      break;
    }
  }

  for (const pattern of repetitionPatterns) {
    if (pattern.test(value)) {
      errors.push(`${field}: repetição textual ruim.`);
      break;
    }
  }
}


// -----------------------------------------------------
// 6. VALIDAÇÕES ESPECÍFICAS
// -----------------------------------------------------

if (
  /apenas aqueles sem interesse/i.test(parsed.who_should_skip || "")
) {
  errors.push(
    "who_should_skip: resposta genérica demais e pouco útil."
  );
}

if (
  /não há perfis específicos/i.test(parsed.who_should_skip || "")
) {
  errors.push(
    "who_should_skip: deveria apontar uma limitação real do evento."
  );
}

if (
  /crescente adoção/i.test(parsed.editorial_angle || "") ||
  /crescente aderência/i.test(parsed.editorial_angle || "")
) {
  errors.push(
    "editorial_angle: afirma tendência regional sem evidência suficiente."
  );
}

if (
  /faz parte de um ecossistema/i.test(parsed.regional_context || "")
) {
  errors.push(
    "regional_context: possível extrapolação regional além das fontes."
  );
}


